{"path":"/root/solve.py","content":"import csv
import json
from pathlib import Path

ROOT = Path('/root')
RUNS_SMALL = 24
RUNS_BULK = 12
SWITCH_THRESHOLD_USD = 7000


def parse_bool(value):
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    return str(value).strip().lower() in {'true', '1', 'yes', 'y'}


def read_csv(path):
    with open(path, newline='', encoding='utf-8') as f:
        return list(csv.DictReader(f))


def money(value):
    return round(float(value), 2)


def main():
    with open(ROOT / 'assay_manifest.json', encoding='utf-8') as f:
        manifest = json.load(f)

    assays = []
    assay_by_label = {}
    for region in manifest.get('regions', []):
        for assay in region.get('assays', []):
            if parse_bool(assay.get('in_scope')):
                assays.append(assay)
                labels = [assay.get('assay_name', '')] + list(assay.get('aliases', []))
                for label in labels:
                    assay_by_label[label] = assay

    carrier_lookup = {
        row['carrier_type']: float(row['carrier_cost_usd'])
        for row in read_csv(ROOT / 'carrier_cost.csv')
    }

    latest_billing_by_assay_id = {}
    for row in read_csv(ROOT / 'billing.csv'):
        if not parse_bool(row.get('is_active')):
            continue
        assay = assay_by_label.get(row.get('assay_label'))
        if assay is None:
            continue
        assay_id = assay['assay_id']
        current = latest_billing_by_assay_id.get(assay_id)
        if current is None or row.get('effective_month', '') > current.get('effective_month', ''):
            latest_billing_by_assay_id[assay_id] = row

    active_labs_by_assay_id = {}
    for row in read_csv(ROOT / 'lab_overrides.csv'):
        if row.get('status') != 'approved':
            continue
        assay_id = row['assay_id']
        revision = int(row['revision'])
        current = active_labs_by_assay_id.get(assay_id)
        if current is None or revision > current['revision']:
            active_labs_by_assay_id[assay_id] = {
                'revision': revision,
                'active_labs': int(row['active_labs']),
            }

    with open(ROOT / 'report_template.json', encoding='utf-8') as f:
        template = json.load(f)

    report_assays = []
    for assay in assays:
        assay_id = assay['assay_id']
        billing = latest_billing_by_assay_id.get(assay_id)
        if billing is None:
            raise ValueError(f'No active billing row found for in-scope assay {assay_id}')

        active_labs = active_labs_by_assay_id.get(
            assay_id,
            {'active_labs': int(assay['default_active_labs'])},
        )['active_labs']
        payment = float(billing['payment_per_run_per_lab_usd'])
        reagent_price = float(assay['reagent_price_per_1000_tests_usd'])
        carrier_cost = carrier_lookup[assay['carrier_type']]

        annual_revenue_small = payment * active_labs * RUNS_SMALL
        annual_revenue_bulk = payment * active_labs * RUNS_BULK
        annual_reagent_cost_small = (
            reagent_price * active_labs * float(assay['tests_per_lab_per_run_small']) * RUNS_SMALL / 1000
        )
        annual_reagent_cost_bulk = (
            reagent_price * active_labs * float(assay['tests_per_lab_per_run_bulk']) * RUNS_BULK / 1000
        )
        annual_carrier_cost_small = carrier_cost * active_labs * RUNS_SMALL
        annual_carrier_cost_bulk = carrier_cost * active_labs * RUNS_BULK
        annual_margin_small = annual_revenue_small - annual_reagent_cost_small - annual_carrier_cost_small
        annual_margin_bulk = annual_revenue_bulk - annual_reagent_cost_bulk - annual_carrier_cost_bulk
        annual_margin_difference = annual_margin_bulk - annual_margin_small

        report_assays.append({
            'assay_id': assay_id,
            'assay_name': assay['assay_name'],
            'active_labs': active_labs,
            'payment_per_run_per_lab_usd': money(payment),
            'carrier_type': assay['carrier_type'],
            'carrier_cost_usd': money(carrier_cost),
            'runs_per_year_small': RUNS_SMALL,
            'runs_per_year_bulk': RUNS_BULK,
            'annual_revenue_small': money(annual_revenue_small),
            'annual_revenue_bulk': money(annual_revenue_bulk),
            'annual_reagent_cost_small': money(annual_reagent_cost_small),
            'annual_reagent_cost_bulk': money(annual_reagent_cost_bulk),
            'annual_carrier_cost_small': money(annual_carrier_cost_small),
            'annual_carrier_cost_bulk': money(annual_carrier_cost_bulk),
            'annual_margin_small': money(annual_margin_small),
            'annual_margin_bulk': money(annual_margin_bulk),
            'annual_margin_difference': money(annual_margin_difference),
        })

    report_assays.sort(key=lambda item: item['assay_id'])

    total_small = money(sum(item['annual_margin_small'] for item in report_assays))
    total_bulk = money(sum(item['annual_margin_bulk'] for item in report_assays))
    total_difference = money(total_bulk - total_small)
    absolute_difference = money(abs(total_difference))
    decision = 'adopt_bulk_kit' if absolute_difference < SWITCH_THRESHOLD_USD else 'keep_small_kit'

    output = {
        'metadata': template['metadata'],
        'analysis': {
            'assumptions': {
                'runs_per_year_small_kit': RUNS_SMALL,
                'runs_per_year_bulk_kit': RUNS_BULK,
                'switch_threshold_usd': SWITCH_THRESHOLD_USD,
                'lab_override_rule': 'highest approved revision per assay_id, else default_active_labs',
                'billing_rule': 'latest active effective_month per assay',
            },
            'assays': report_assays,
            'totals': {
                'total_annual_margin_small_kit_usd': total_small,
                'total_annual_margin_bulk_kit_usd': total_bulk,
                'total_annual_margin_difference': total_difference,
                'absolute_total_margin_difference': absolute_difference,
            },
            'recommendation': {
                'decision': decision,
            },
        },
    }

    with open(ROOT / 'reagent_policy_report.json', 'w', encoding='utf-8') as f:
        json.dump(output, f, indent=2)
        f.write('\n')

    summary_lines = [
        f'Total small-kit margin (USD): ${total_small:.2f}',
        f'Total bulk-kit margin (USD): ${total_bulk:.2f}',
        f'Absolute difference (USD): ${absolute_difference:.2f}',
        f'Decision: {decision}',
    ]
    with open(ROOT / 'reagent_policy_summary.md', 'w', encoding='utf-8') as f:
        f.write('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
